ALTER TABLE contacts ADD CONSTRAINT contacts_tenant_id_unique UNIQUE(tenant_id,id);
CREATE TABLE private_documents(id uuid PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES tenants(id),course_id uuid,contact_id uuid,kind text NOT NULL,title text NOT NULL,mime text NOT NULL CHECK(mime IN ('application/pdf','image/jpeg','image/png')),bytes integer NOT NULL CHECK(bytes>0 AND bytes<=1048576),digest text NOT NULL,encrypted_payload text NOT NULL,status text NOT NULL CHECK(status IN ('quarantined','received','verified','rejected','expired','deleted')),scan_status text NOT NULL CHECK(scan_status IN ('pending','clean','infected','unavailable')),created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),reviewed_by uuid REFERENCES users(id),reviewed_at timestamptz,expires_at timestamptz,retention_until timestamptz NOT NULL DEFAULT now()+interval '30 days',legal_hold boolean NOT NULL DEFAULT false,version integer NOT NULL DEFAULT 1,FOREIGN KEY(tenant_id,course_id) REFERENCES courses(tenant_id,id),FOREIGN KEY(tenant_id,contact_id) REFERENCES contacts(tenant_id,id),CHECK(course_id IS NOT NULL OR contact_id IS NOT NULL));
CREATE TABLE document_grants(id uuid PRIMARY KEY,document_id uuid NOT NULL REFERENCES private_documents(id),target_tenant_id uuid NOT NULL REFERENCES tenants(id),target_user_id uuid NOT NULL REFERENCES users(id),expires_at timestamptz NOT NULL,revoked boolean NOT NULL DEFAULT false,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON private_documents,document_grants FROM PUBLIC,taxilink_app,taxilink_identity;
CREATE FUNCTION actor_mfa_enabled() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT EXISTS(SELECT 1 FROM users WHERE id::text=current_setting('app.user_id',true) AND mfa_secret IS NOT NULL) $$;
CREATE FUNCTION document_access(did uuid,editing boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM private_documents d WHERE d.id=did AND ((d.tenant_id::text=current_setting('app.tenant_id',true) AND actor_has_role(ARRAY['admin','dispatcher'])) OR (NOT editing AND d.status IN ('received','verified') AND d.scan_status='clean' AND (d.expires_at IS NULL OR d.expires_at>now()) AND EXISTS(SELECT 1 FROM document_grants g JOIN memberships m ON m.tenant_id=g.target_tenant_id AND m.user_id=g.target_user_id WHERE g.document_id=d.id AND NOT g.revoked AND g.expires_at>now() AND m.active AND g.target_tenant_id::text=current_setting('app.tenant_id',true) AND g.target_user_id::text=current_setting('app.user_id',true) AND EXISTS(SELECT 1 FROM courses c JOIN assignments a ON a.course_id=c.id JOIN drivers dr ON dr.id=a.driver_id WHERE c.tenant_id=g.target_tenant_id AND (c.id=d.course_id OR c.source_course_id=d.course_id) AND c.status IN ('assigned','confirmed','approaching','onboard') AND (dr.user_id=g.target_user_id OR actor_has_role(ARRAY['admin','dispatcher'])))))));
 $$;
CREATE FUNCTION list_private_documents() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT COALESCE(jsonb_agg(to_jsonb(x) ORDER BY x.created_at DESC),'[]') FROM (SELECT id,course_id,contact_id,kind,title,mime,bytes,status,scan_status,created_at,expires_at,retention_until,legal_hold,version,tenant_id::text=current_setting('app.tenant_id',true) AS owned FROM private_documents WHERE document_access(id,false) LIMIT 500) x;
 $$;
CREATE FUNCTION read_private_document(did uuid,editing boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d private_documents;BEGIN
 IF NOT document_access(did,editing) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001';END IF;
 SELECT * INTO d FROM private_documents WHERE id=did;RETURN to_jsonb(d);END $$;
CREATE FUNCTION save_private_document(d jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result uuid:=gen_random_uuid();cid uuid;pid uuid;BEGIN
 IF NOT actor_has_role(ARRAY['admin','dispatcher']) THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P0001';END IF;
 cid:=(d->>'course_id')::uuid;pid:=(d->>'contact_id')::uuid;
 IF (cid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM courses WHERE id=cid AND tenant_id::text=current_setting('app.tenant_id') AND source_course_id IS NULL)) OR (pid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM contacts WHERE id=pid AND tenant_id::text=current_setting('app.tenant_id'))) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001';END IF;
 IF (SELECT count(*) FROM private_documents WHERE tenant_id::text=current_setting('app.tenant_id') AND status<>'deleted' AND ((cid IS NOT NULL AND course_id=cid) OR (pid IS NOT NULL AND contact_id=pid)))>=20 THEN RAISE EXCEPTION 'DOCUMENT_LIMIT' USING ERRCODE='P0001';END IF;
 INSERT INTO private_documents(id,tenant_id,course_id,contact_id,kind,title,mime,bytes,digest,encrypted_payload,status,scan_status,created_by,expires_at) VALUES(result,current_setting('app.tenant_id')::uuid,cid,pid,d->>'kind',d->>'title',d->>'mime',(d->>'bytes')::integer,d->>'digest',d->>'encrypted_payload',d->>'status',d->>'scan_status',current_setting('app.user_id')::uuid,(d->>'expires_at')::timestamptz);
 PERFORM collaboration_audit(current_setting('app.tenant_id')::uuid,'document.uploaded',result);RETURN result;END $$;
CREATE FUNCTION review_private_document(did uuid,expected integer,new_status text,scan text DEFAULT NULL,hold boolean DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE d private_documents;BEGIN
 IF NOT document_access(did,true) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001';END IF;
 SELECT * INTO d FROM private_documents WHERE id=did FOR UPDATE;
 IF d.version<>expected THEN RAISE EXCEPTION 'PLAN_STALE' USING ERRCODE='P0001';END IF;
 IF new_status NOT IN ('quarantined','received','verified','rejected','expired','deleted') THEN RAISE EXCEPTION 'INVALID_TRANSITION' USING ERRCODE='P0001';END IF;
 IF new_status IN ('received','verified') AND COALESCE(scan,d.scan_status)<>'clean' THEN RAISE EXCEPTION 'DOCUMENT_QUARANTINED' USING ERRCODE='P0001';END IF;
 IF new_status='verified' AND d.expires_at<=now() THEN RAISE EXCEPTION 'DOCUMENT_EXPIRED' USING ERRCODE='P0001';END IF;
 IF new_status='deleted' AND (d.legal_hold OR NOT actor_has_role(ARRAY['admin']) OR NOT actor_mfa_enabled()) THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P0001';END IF;
 IF hold IS NOT NULL AND (NOT actor_has_role(ARRAY['admin']) OR NOT actor_mfa_enabled()) THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P0001';END IF;
 UPDATE private_documents SET status=new_status,scan_status=COALESCE(scan,scan_status),reviewed_by=current_setting('app.user_id')::uuid,reviewed_at=now(),legal_hold=COALESCE(hold,legal_hold),encrypted_payload=CASE WHEN new_status='deleted' THEN '' ELSE encrypted_payload END,version=version+1 WHERE id=did;
 IF new_status IN ('rejected','expired','deleted') THEN UPDATE document_grants SET revoked=true WHERE document_id=did;END IF;
 PERFORM collaboration_audit(d.tenant_id,'document.'||new_status,did);END $$;
CREATE FUNCTION grant_private_document(did uuid,target_user uuid,target_tenant uuid,until_at timestamptz) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result uuid:=gen_random_uuid();d private_documents;BEGIN
 IF NOT document_access(did,true) OR NOT actor_has_role(ARRAY['admin']) OR NOT actor_mfa_enabled() THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P0001';END IF;
 SELECT * INTO d FROM private_documents WHERE id=did;
 IF d.status NOT IN ('received','verified') OR d.scan_status<>'clean' OR until_at<=now() OR until_at>now()+interval '24 hours' THEN RAISE EXCEPTION 'DOCUMENT_QUARANTINED' USING ERRCODE='P0001';END IF;
 IF NOT EXISTS(SELECT 1 FROM memberships m JOIN courses c ON c.tenant_id=m.tenant_id JOIN assignments a ON a.course_id=c.id JOIN drivers dr ON dr.id=a.driver_id WHERE m.user_id=target_user AND m.tenant_id=target_tenant AND m.active AND m.role IN ('admin','dispatcher','driver') AND (c.id=d.course_id OR c.source_course_id=d.course_id) AND c.status IN ('assigned','confirmed','approaching','onboard') AND (dr.user_id=target_user OR m.role IN ('admin','dispatcher'))) THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P0001';END IF;
 INSERT INTO document_grants(id,document_id,target_tenant_id,target_user_id,expires_at,created_by) VALUES(result,did,target_tenant,target_user,until_at,current_setting('app.user_id')::uuid);
 PERFORM collaboration_audit(d.tenant_id,'document.granted',did);RETURN result;END $$;
CREATE FUNCTION revoke_private_document(gid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE did uuid;BEGIN
 SELECT document_id INTO did FROM document_grants WHERE id=gid;
 IF NOT document_access(did,true) OR NOT actor_has_role(ARRAY['admin']) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001';END IF;
 UPDATE document_grants SET revoked=true WHERE id=gid;PERFORM collaboration_audit(current_setting('app.tenant_id')::uuid,'document.grant_revoked',did);END $$;
CREATE FUNCTION private_document_grants(did uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ BEGIN
 IF NOT document_access(did,true) OR NOT actor_has_role(ARRAY['admin']) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P0001';END IF;
 RETURN (SELECT COALESCE(jsonb_agg(to_jsonb(g)),'[]') FROM document_grants g WHERE document_id=did);END $$;
REVOKE ALL ON FUNCTION actor_mfa_enabled(),document_access(uuid,boolean),list_private_documents(),read_private_document(uuid,boolean),save_private_document(jsonb),review_private_document(uuid,integer,text,text,boolean),grant_private_document(uuid,uuid,uuid,timestamptz),revoke_private_document(uuid),private_document_grants(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION actor_mfa_enabled(),list_private_documents(),read_private_document(uuid,boolean),save_private_document(jsonb),review_private_document(uuid,integer,text,text,boolean),grant_private_document(uuid,uuid,uuid,timestamptz),revoke_private_document(uuid),private_document_grants(uuid) TO taxilink_app;
